"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[9603],{4128(e,n,t){t.r(n),t.d(n,{assets:()=>c,contentTitle:()=>l,default:()=>m,frontMatter:()=>r,metadata:()=>a,toc:()=>p});const a=JSON.parse('{"id":"part2-backend-platform-security/pydantic-data-models","title":"Pydantic Data Models: From Python Classes to API Contracts","description":"FastAPI uses Pydantic because web applications live at the boundary between untyped external data and typed Python code. This chapter starts from ordinary Python classes, moves through dataclasses, then shows why Pyda...","source":"@site/docs/part2-backend-platform-security/04-pydantic-data-models.mdx","sourceDirName":"part2-backend-platform-security","slug":"/part2-backend-platform-security/04-pydantic-data-models","permalink":"/tutorials/part2-backend-platform-security/04-pydantic-data-models","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"sidebarPosition":4,"frontMatter":{"title":"Pydantic Data Models: From Python Classes to API Contracts","slug":"/part2-backend-platform-security/04-pydantic-data-models","description":"FastAPI uses Pydantic because web applications live at the boundary between untyped external data and typed Python code. This chapter starts from ordinary Python classes, moves through dataclasses, then shows why Pyda...","sidebar_label":"4. Pydantic data models","pagination_label":"4. Pydantic data models","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"3. FastAPI request mapping","permalink":"/tutorials/part2-backend-platform-security/03-fastapi-request-mapping"},"next":{"title":"5. Concurrency and user isolation","permalink":"/tutorials/part2-backend-platform-security/04-concurrency-user-isolation"}}');var o=t(4848),s=t(8453),i=t(8172);const d=JSON.parse('{"sourcePath":"part2-backend-platform-security/04-pydantic-data-models.html","route":"/part2-backend-platform-security/04-pydantic-data-models","kind":"chapter","partId":"part2","partLabel":"Part II - Backend, Platform & Security","accent":"teal","heading":"Pydantic Data Models: From Python Classes to API Contracts","title":"Pydantic Data Models: From Python Classes to API Contracts","description":"FastAPI uses Pydantic because web applications live at the boundary between untyped external data and typed Python code. This chapter starts from ordinary Python classes, moves through dataclasses, then shows why Pyda...","readingMinutes":22,"bodyClass":"","normalizeMath":false,"toc":[{"id":"1-start-with-python-objects-class-variables-instance-variables-and-init","label":"1) Start with Python Objects: Class Variables, Instance Variables, and __init__"},{"id":"2-the-data-problem-before-pydantic","label":"2) The Data Problem Before Pydantic"},{"id":"3-dataclasses-the-first-improvement","label":"3) Dataclasses: The First Improvement"},{"id":"4-why-pydantic-exists","label":"4) Why Pydantic Exists"},{"id":"5-pydantic-models-dataclass-ergonomics-runtime-validation","label":"5) Pydantic Models: Dataclass Ergonomics + Runtime Validation"},{"id":"6-validation-errors-are-part-of-the-contract","label":"6) Validation Errors Are Part of the Contract"},{"id":"7-required-optional-nullable-and-defaults","label":"7) Required, Optional, Nullable, and Defaults"},{"id":"8-field-constraints-with-field","label":"8) Field Constraints with Field"},{"id":"9-coercion-mode-vs-strict-mode","label":"9) Coercion Mode vs Strict Mode"},{"id":"10-aliases-json-camelcase-and-python-snake-case","label":"10) Aliases: JSON camelCase and Python snake_case"},{"id":"11-nested-models","label":"11) Nested Models"},{"id":"12-validators-field-level-and-model-level-rules","label":"12) Validators: Field-Level and Model-Level Rules"},{"id":"13-model-configuration-class-level-behavior-for-fields","label":"13) Model Configuration: Class-Level Behavior for Fields"},{"id":"14-deserialization-and-serialization","label":"14) Deserialization and Serialization"},{"id":"15-json-schema-and-openapi","label":"15) JSON Schema and OpenAPI"},{"id":"16-typeadapter-validate-a-type-without-creating-a-model","label":"16) TypeAdapter: Validate a Type Without Creating a Model"},{"id":"17-settings-management-with-pydantic-settings","label":"17) Settings Management with pydantic-settings"},{"id":"18-fastapi-integration-request-and-response-contracts","label":"18) FastAPI Integration: Request and Response Contracts"},{"id":"19-external-api-and-queue-message-validation","label":"19) External API and Queue Message Validation"},{"id":"20-llm-output-validation","label":"20) LLM Output Validation"},{"id":"21-pydantic-dataclasses","label":"21) Pydantic Dataclasses"},{"id":"22-practical-design-patterns","label":"22) Practical Design Patterns"},{"id":"23-common-pitfalls","label":"23) Common Pitfalls"},{"id":"24-end-to-end-example-api-payload-alias-validation-and-response","label":"24) End-to-End Example: API Payload, Alias, Validation, and Response"},{"id":"25-decision-guide","label":"25) Decision Guide"},{"id":"26-what-to-remember","label":"26) What to Remember"},{"id":"official-references","label":"Official references"}],"html":"<p class=\\"lead\\">FastAPI uses Pydantic because web applications live at the\\nboundary between untyped external data and typed Python code. This chapter\\nstarts from ordinary Python classes, moves through dataclasses, then shows why\\nPydantic became the standard way to validate JSON, serialize objects, manage\\nsettings, and enforce structured LLM outputs.</p>\\n\\n<div class=\\"tr-note\\">\\n  <strong>Where this fits in the book</strong>\\n  Chapter 3 showed how FastAPI maps HTTP requests into function arguments.\\n  This chapter explains the data model layer behind that mapping. After this,\\n  the concurrency, authentication, tenancy, and integration chapters can rely\\n  on one consistent idea: external data must be validated at the boundary and\\n  converted into explicit Python objects before business logic touches it.\\n</div>\\n\\n<h2 id=\\"1-start-with-python-objects-class-variables-instance-variables-and-init\\">1) Start with Python Objects: Class Variables, Instance Variables, and <code>__init__</code></h2>\\n\\n<p>Before Pydantic makes sense, the reader needs a clear mental model of a\\nnormal Python object. A class is the blueprint. An instance is one concrete\\nobject built from that blueprint. Variables can live in either place, and that\\ndifference matters when you model API data.</p>\\n\\n<pre><code class=\\"language-python\\">class User:\\n    species = \\"human\\"          # class variable: shared by the class\\n\\n    def __init__(self, user_id: int, name: str):\\n        self.user_id = user_id # instance variable: belongs to this object\\n        self.name = name       # instance variable: belongs to this object\\n\\nalice = User(1, \\"Alice\\")\\nbob = User(2, \\"Bob\\")\\n\\nprint(alice.name)     # Alice\\nprint(bob.name)       # Bob\\nprint(User.species)   # human</code></pre>\\n\\n<p><code>__init__</code> is the initializer that runs after Python creates a\\nnew object. It is where ordinary classes usually copy constructor arguments\\nonto <code>self</code>. In the example above, <code>alice.name</code> and\\n<code>bob.name</code> are different because each instance has its own\\n<code>name</code> attribute.</p>\\n\\n<div class=\\"tr-note\\">\\n  <strong>Precise wording:</strong> <code>__init__</code> creates or assigns\\n  instance variables on <code>self</code>. A class variable belongs to the\\n  class object itself and is shared by instances unless an instance overrides\\n  that attribute with its own value.\\n</div>\\n\\n<h3 id=\\"why-class-variables-can-surprise-you\\">Why class variables can surprise you</h3>\\n\\n<p>Class variables are useful for constants, shared configuration, registries,\\nor metadata. They are dangerous when you accidentally use them for per-object\\nstate, especially with mutable values such as lists or dictionaries.</p>\\n\\n<pre><code class=\\"language-python\\">class BadCart:\\n    items: list[str] = []  # shared class-level list, not per-cart state\\n\\ncart_a = BadCart()\\ncart_b = BadCart()\\n\\ncart_a.items.append(\\"keyboard\\")\\nprint(cart_b.items)\\n# [\\"keyboard\\"]  # cart_b sees cart_a\'s item because the list is shared</code></pre>\\n\\n<p>The correct plain-class version creates the mutable list inside\\n<code>__init__</code>, so every instance gets its own list.</p>\\n\\n<pre><code class=\\"language-python\\">class Cart:\\n    def __init__(self):\\n        self.items: list[str] = []\\n\\ncart_a = Cart()\\ncart_b = Cart()\\n\\ncart_a.items.append(\\"keyboard\\")\\nprint(cart_b.items)\\n# []</code></pre>\\n\\n<h3 id=\\"what-classmethod-is-actually-for\\">What <code>@classmethod</code> is actually for</h3>\\n\\n<p>A class method receives the class as <code>cls</code> instead of receiving\\none instance as <code>self</code>. It does not make class variables belong to\\nan instance. It is most often used for alternate constructors, factories, and\\nlogic that should respect subclasses.</p>\\n\\n<pre><code class=\\"language-python\\">class User:\\n    default_active = True\\n\\n    def __init__(self, user_id: int, name: str, active: bool):\\n        self.user_id = user_id\\n        self.name = name\\n        self.active = active\\n\\n    @classmethod\\n    def from_dict(cls, data: dict) -&gt; \\"User\\":\\n        active = data.get(\\"active\\", cls.default_active)\\n        if isinstance(active, str):\\n            active = active.lower()\\n            if active in {\\"true\\", \\"1\\", \\"yes\\"}:\\n                active = True\\n            elif active in {\\"false\\", \\"0\\", \\"no\\"}:\\n                active = False\\n            else:\\n                raise ValueError(\\"active must be true or false\\")\\n\\n        return cls(\\n            user_id=int(data[\\"user_id\\"]),\\n            name=str(data[\\"name\\"]),\\n            active=active,\\n        )\\n\\nuser = User.from_dict({\\"user_id\\": \\"123\\", \\"name\\": \\"Alice\\"})\\nprint(user.active)\\n# True</code></pre>\\n\\n<p>This example is already moving toward structured data modeling. We are manually doing\\nconversion, defaults, and object construction inside <code>from_dict</code>.\\nThat works for tiny examples, but it becomes repetitive and error-prone when\\npayloads are nested, fields are optional, constraints matter, error messages\\nmust be precise, and OpenAPI schema needs to be generated.</p>\\n\\n<h2 id=\\"2-the-data-problem-before-pydantic\\">2) The Data Problem Before Pydantic</h2>\\n\\n<h3 id=\\"json-has-fewer-types-than-python\\">JSON has fewer types than Python</h3>\\n\\n<p>JSON is the common language of HTTP APIs, browser clients, queues, config\\nfiles, and many LLM tool calls. It has only a small set of data types:</p>\\n\\n<table>\\n  <thead>\\n    <tr><th>JSON type</th><th>Example</th><th>Python usually wants</th></tr>\\n  </thead>\\n  <tbody>\\n    <tr><td>string</td><td><code>\\"Alice\\"</code></td><td><code>str</code>, sometimes <code>datetime</code>, <code>EmailStr</code>, <code>UUID</code>, <code>Enum</code></td></tr>\\n    <tr><td>number</td><td><code>30</code>, <code>19.99</code></td><td><code>int</code>, <code>float</code>, <code>Decimal</code></td></tr>\\n    <tr><td>boolean</td><td><code>true</code>, <code>false</code></td><td><code>bool</code></td></tr>\\n    <tr><td>null</td><td><code>null</code></td><td><code>None</code>, only if the field is nullable</td></tr>\\n    <tr><td>array</td><td><code>[\\"Python\\", \\"FastAPI\\"]</code></td><td><code>list[str]</code>, <code>tuple</code>, <code>set</code></td></tr>\\n    <tr><td>object</td><td><code>{\\"city\\": \\"Sydney\\"}</code></td><td>nested model, typed dict, dictionary</td></tr>\\n  </tbody>\\n</table>\\n\\n<p>That mismatch explains why validation belongs at the API boundary. JSON does\\nnot know what a Python <code>datetime</code>, <code>UUID</code>, enum, or domain\\nobject is. Your code has to decide what to accept, what to convert, what to\\nreject, and what error to return.</p>\\n\\n<h3 id=\\"plain-python-classes-hold-data-but-do-not-validate-input\\">Plain Python classes hold data but do not validate input</h3>\\n\\n<pre><code class=\\"language-python\\">class User:\\n    def __init__(self, id: int, name: str, active: bool = True):\\n        self.id = id\\n        self.name = name\\n        self.active = active\\n\\nuser = User(id=\\"123\\", name=42, active=\\"yes\\")\\nprint(user.id, user.name, user.active)\\n# \\"123\\" 42 \\"yes\\"   # type hints did not validate anything at runtime</code></pre>\\n\\n<p>Python type hints help editors, static type checkers, and humans. They do\\nnot automatically validate runtime values. Without extra code, the constructor\\naccepts whatever the caller passes.</p>\\n\\n<h3 id=\\"manual-validation-quickly-becomes-repetitive\\">Manual validation quickly becomes repetitive</h3>\\n\\n<p>You can write validation yourself inside <code>__init__</code> or a\\n<code>@classmethod</code> factory, but every model then needs its own parsing,\\nconversion, defaults, error messages, and nested-object handling.</p>\\n\\n<pre><code class=\\"language-python\\">class User:\\n    def __init__(self, id: int, name: str, active: bool = True):\\n        if not isinstance(id, int):\\n            raise TypeError(\\"id must be an integer\\")\\n        if not isinstance(name, str):\\n            raise TypeError(\\"name must be a string\\")\\n        if not isinstance(active, bool):\\n            raise TypeError(\\"active must be a boolean\\")\\n\\n        self.id = id\\n        self.name = name\\n        self.active = active\\n\\n    @classmethod\\n    def from_json_dict(cls, data: dict) -&gt; \\"User\\":\\n        active = data.get(\\"active\\", True)\\n        if isinstance(active, str):\\n            active = active.lower()\\n            if active in {\\"true\\", \\"1\\", \\"yes\\"}:\\n                active = True\\n            elif active in {\\"false\\", \\"0\\", \\"no\\"}:\\n                active = False\\n            else:\\n                raise ValueError(\\"active must be true or false\\")\\n\\n        return cls(\\n            id=int(data[\\"id\\"]),\\n            name=str(data[\\"name\\"]),\\n            active=active,\\n        )</code></pre>\\n\\n<p>This is the bridge to Pydantic: the industry-standard version should keep\\nthe readable class shape, but make validation, conversion, error reporting,\\nschema generation, and nested parsing consistent instead of hand-written in\\nevery constructor.</p>\\n\\n<h2 id=\\"3-dataclasses-the-first-improvement\\">3) Dataclasses: The First Improvement</h2>\\n\\n<p>Python dataclasses are the natural next step after a hand-written\\n<code>__init__</code>. They let you describe the data fields once, then Python\\ngenerates the repetitive object methods for you.</p>\\n\\n<pre><code class=\\"language-python\\">from dataclasses import dataclass, field\\n\\n@dataclass\\nclass User:\\n    id: int\\n    name: str\\n    roles: list[str] = field(default_factory=list)\\n\\nuser = User(id=\\"123\\", name=42)\\nprint(user)\\n# User(id=\'123\', name=42, roles=[])</code></pre>\\n\\n<p>The annotation syntax looks similar to a Pydantic model, but at this stage\\nit is still just Python dataclass machinery. The type hints define the fields\\nused to generate methods; they do not automatically validate runtime values.</p>\\n\\n<table>\\n  <thead>\\n    <tr><th>Generated method</th><th>What the dataclass gives you</th></tr>\\n  </thead>\\n  <tbody>\\n    <tr><td><code>__init__</code></td><td>Creates an initializer with parameters for the declared fields.</td></tr>\\n    <tr><td><code>__repr__</code></td><td>Returns a readable string representation such as <code>User(id=...)</code>.</td></tr>\\n    <tr><td><code>__eq__</code></td><td>Compares two instances by field values.</td></tr>\\n    <tr><td><code>__hash__</code></td><td>Generated only when the class is immutable/frozen enough to be hashable.</td></tr>\\n    <tr><td><code>__post_init__</code></td><td>Optional hook that runs after <code>__init__</code> for extra setup or manual validation.</td></tr>\\n  </tbody>\\n</table>\\n\\n<h3 id=\\"class-variables-in-dataclasses-use-classvar\\">Class variables in dataclasses: use <code>ClassVar</code></h3>\\n\\n<p>If a value belongs to the class and should not be treated as an instance\\nfield, annotate it with <code>ClassVar</code>. This is how you keep constants\\nor shared metadata out of the generated <code>__init__</code>.</p>\\n\\n<pre><code class=\\"language-python\\">from dataclasses import dataclass\\nfrom typing import ClassVar\\n\\n@dataclass\\nclass User:\\n    species: ClassVar[str] = \\"Homo sapiens\\"  # not part of __init__\\n    name: str\\n    age: int\\n\\nuser = User(name=\\"Alice\\", age=30)\\nprint(user.species)\\n# Homo sapiens</code></pre>\\n\\n<h3 id=\\"mutable-defaults-use-default-factory\\">Mutable defaults: use <code>default_factory</code></h3>\\n\\n<p>The same shared-mutable-value problem exists in dataclass-style modeling.\\nIf each instance should get its own list, dictionary, or set, create it with a\\nfactory.</p>\\n\\n<pre><code class=\\"language-python\\">from dataclasses import dataclass, field\\n\\n@dataclass\\nclass Team:\\n    members: list[str] = field(default_factory=list)\\n\\nteam_a = Team()\\nteam_b = Team()\\n\\nteam_a.members.append(\\"Alice\\")\\nprint(team_a.members)  # [\\"Alice\\"]\\nprint(team_b.members)  # []</code></pre>\\n\\n<p>This is the same idea as avoiding mutable default arguments in functions:</p>\\n\\n<pre><code class=\\"language-python\\">def add_name(name: str, names: list[str] = []):  # avoid this\\n    names.append(name)\\n    return names</code></pre>\\n\\n<p>The list is created once when the function is defined, not once per call.\\nDataclasses force you toward <code>default_factory</code> because per-instance\\nstate should be created per instance.</p>\\n\\n<h3 id=\\"dataclasses-still-do-not-validate-input-types\\">Dataclasses still do not validate input types</h3>\\n\\n<p>Dataclasses solve boilerplate, representation, equality, and mutable default\\nsetup, but they still do not validate types by default. <code>id=\\"123\\"</code>\\nand <code>name=42</code> are accepted because dataclasses are data containers,\\nnot runtime validators.</p>\\n\\n<p>You can add manual checks in <code>__post_init__</code>, but then you are\\nback to writing custom validation logic for every class.</p>\\n\\n<pre><code class=\\"language-python\\">from dataclasses import dataclass\\n\\n@dataclass\\nclass User:\\n    id: int\\n    name: str\\n\\n    def __post_init__(self):\\n        if not isinstance(self.id, int):\\n            raise TypeError(\\"id must be an integer\\")\\n        if not isinstance(self.name, str):\\n            raise TypeError(\\"name must be a string\\")</code></pre>\\n\\n<div class=\\"tr-warning\\">\\n  <strong>Industry distinction:</strong> use a dataclass when data is already\\n  trusted and you want a lightweight internal container. Use Pydantic when data\\n  crosses a boundary: HTTP request, queue event, file, environment variable,\\n  third-party API response, database document, or LLM output.\\n</div>\\n\\n<h2 id=\\"4-why-pydantic-exists\\">4) Why Pydantic Exists</h2>\\n\\n<p>Most backend bugs at API boundaries are not caused by complicated algorithms.\\nThey are caused by ordinary shape mismatches:</p>\\n\\n<ul>\\n  <li>The client sends <code>\\"age\\": \\"30\\"</code> but Python code expects <code>age: int</code>.</li>\\n  <li>The frontend uses <code>personalEmail</code> but Python code should use <code>personal_email</code>.</li>\\n  <li>A required field is missing, but the function assumes it exists.</li>\\n  <li>A nested payload has the correct outer shape but invalid inner objects.</li>\\n  <li>An LLM returns text that looks like JSON but is not the contract your code promised to handle.</li>\\n</ul>\\n\\n<p>Pydantic was introduced to solve this boundary problem using Python type\\nannotations. It gives you a class that still feels like normal Python, but it\\nadds runtime validation, conversion, error reporting, JSON schema generation,\\nserialization, and integration hooks used by frameworks such as FastAPI.</p>\\n\\n<div class=\\"tr-callout\\">\\n  <strong>Core mental model:</strong> Pydantic turns unreliable outside data\\n  into reliable inside objects. Your API should accept dictionaries/JSON at the\\n  boundary, validate them once, then pass typed objects through the rest of the\\n  system.\\n</div>\\n\\n<div class=\\"figure-card\\">\\n  <h3 id=\\"visual-boundary-validation\\">Visual: boundary validation</h3>\\n  <svg class=\\"viz\\" viewBox=\\"0 0 980 250\\" role=\\"img\\" aria-label=\\"Pydantic boundary validation flow\\">\\n    <defs>\\n      <marker id=\\"pydantic-arrow\\" viewBox=\\"0 0 10 10\\" refX=\\"9\\" refY=\\"5\\" markerWidth=\\"8\\" markerHeight=\\"8\\" orient=\\"auto-start-reverse\\">\\n        <path d=\\"M 0 0 L 10 5 L 0 10 z\\" fill=\\"#0969da\\" stroke=\\"none\\"></path>\\n      </marker>\\n      <marker id=\\"pydantic-arrow-purple\\" viewBox=\\"0 0 10 10\\" refX=\\"9\\" refY=\\"5\\" markerWidth=\\"8\\" markerHeight=\\"8\\" orient=\\"auto-start-reverse\\">\\n        <path d=\\"M 0 0 L 10 5 L 0 10 z\\" fill=\\"#8250df\\" stroke=\\"none\\"></path>\\n      </marker>\\n    </defs>\\n    <rect x=\\"40\\" y=\\"54\\" width=\\"210\\" height=\\"120\\" rx=\\"14\\" fill=\\"#fff8e6\\" stroke=\\"#bf8700\\" stroke-width=\\"1.5\\"></rect>\\n    <text x=\\"145\\" y=\\"88\\" text-anchor=\\"middle\\" fill=\\"#1f2328\\" style=\\"font-weight:700\\">External data</text>\\n    <text x=\\"145\\" y=\\"116\\" text-anchor=\\"middle\\" fill=\\"#59636e\\">JSON, form, env vars</text>\\n    <text x=\\"145\\" y=\\"144\\" text-anchor=\\"middle\\" fill=\\"#59636e\\">LLM output, API response</text>\\n\\n    <rect x=\\"360\\" y=\\"42\\" width=\\"260\\" height=\\"144\\" rx=\\"14\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\" stroke-width=\\"1.5\\"></rect>\\n    <text x=\\"490\\" y=\\"80\\" text-anchor=\\"middle\\" fill=\\"#1f2328\\" style=\\"font-weight:700\\">Pydantic model</text>\\n    <text x=\\"490\\" y=\\"110\\" text-anchor=\\"middle\\" fill=\\"#334155\\">validate + convert</text>\\n    <text x=\\"490\\" y=\\"138\\" text-anchor=\\"middle\\" fill=\\"#334155\\">report precise errors</text>\\n    <text x=\\"490\\" y=\\"166\\" text-anchor=\\"middle\\" fill=\\"#59636e\\">generate schema/docs</text>\\n\\n    <rect x=\\"730\\" y=\\"54\\" width=\\"210\\" height=\\"120\\" rx=\\"14\\" fill=\\"#f3f8f1\\" stroke=\\"#1a7f37\\" stroke-width=\\"1.5\\"></rect>\\n    <text x=\\"835\\" y=\\"88\\" text-anchor=\\"middle\\" fill=\\"#1f2328\\" style=\\"font-weight:700\\">Python object</text>\\n    <text x=\\"835\\" y=\\"116\\" text-anchor=\\"middle\\" fill=\\"#59636e\\">known fields</text>\\n    <text x=\\"835\\" y=\\"144\\" text-anchor=\\"middle\\" fill=\\"#59636e\\">known types</text>\\n\\n    <line x1=\\"250\\" y1=\\"114\\" x2=\\"360\\" y2=\\"114\\" stroke=\\"#0969da\\" stroke-width=\\"2\\" fill=\\"none\\" marker-end=\\"url(#pydantic-arrow)\\"></line>\\n    <line x1=\\"620\\" y1=\\"114\\" x2=\\"730\\" y2=\\"114\\" stroke=\\"#0969da\\" stroke-width=\\"2\\" fill=\\"none\\" marker-end=\\"url(#pydantic-arrow)\\"></line>\\n    <path d=\\"M 490 188 C 500 224 250 224 190 176\\" stroke=\\"#8250df\\" stroke-width=\\"2\\" fill=\\"none\\" marker-end=\\"url(#pydantic-arrow-purple)\\"></path>\\n    <text x=\\"360\\" y=\\"238\\" text-anchor=\\"middle\\" fill=\\"#59636e\\">invalid input becomes a structured validation error</text>\\n  </svg>\\n</div>\\n\\n<h2 id=\\"5-pydantic-models-dataclass-ergonomics-runtime-validation\\">5) Pydantic Models: Dataclass Ergonomics + Runtime Validation</h2>\\n\\n<p>A Pydantic model is a class that inherits from <code>BaseModel</code>. It\\nuses annotations like a dataclass, generates a constructor like a dataclass,\\nbut also validates and converts data at runtime.</p>\\n\\n<p>In Pydantic language, the class is usually called a <strong>model</strong>.\\nInheritance is what gives the class its extra behavior: <code>BaseModel</code>\\nreads the annotations, builds model fields, creates validation logic, and adds\\nmethods for deserialization, serialization, error reporting, and schema\\ngeneration.</p>\\n\\n<pre><code class=\\"language-python\\">from pydantic import BaseModel\\n\\nclass User(BaseModel):\\n    id: int\\n    name: str\\n    active: bool = True\\n    roles: list[str] = []\\n\\nuser = User(id=\\"123\\", name=\\"Alice\\", active=\\"true\\")\\nprint(user)\\n# id=123 name=\'Alice\' active=True roles=[]</code></pre>\\n\\n<p>Several important things happened:</p>\\n\\n<ul>\\n  <li><code>\\"123\\"</code> became <code>123</code> because the field is <code>int</code>.</li>\\n  <li><code>\\"true\\"</code> became <code>True</code> because the field is <code>bool</code>.</li>\\n  <li>The model has a clear set of fields: <code>id</code>, <code>name</code>, <code>active</code>, <code>roles</code>.</li>\\n  <li>Pydantic handles mutable defaults safely by copying them per instance.</li>\\n</ul>\\n\\n<p>That default conversion behavior is useful for APIs because JSON, query\\nparameters, forms, environment variables, and CSV values often arrive as\\nstrings. If you want no conversion, use strict mode, covered below.</p>\\n\\n<h3 id=\\"three-common-ways-to-create-or-deserialize-a-model\\">Three common ways to create or deserialize a model</h3>\\n\\n<p>The deck uses an important flow here: once the model exists, there are\\nthree practical ways data enters it.</p>\\n\\n<pre><code class=\\"language-python\\">from pydantic import BaseModel\\n\\nclass User(BaseModel):\\n    name: str\\n    age: int\\n\\n# 1) Constructor: common when values are already in Python code\\nu1 = User(name=\\"Alice Smith\\", age=30)\\n\\n# 2) model_validate: validate a Python dict/object, common after JSON parsing\\npayload = {\\"name\\": \\"Bob Jones\\", \\"age\\": \\"25\\"}\\nu2 = User.model_validate(payload)\\n\\n# 3) model_validate_json: validate raw JSON text directly\\njson_str = \'{\\"name\\": \\"Carol Lee\\", \\"age\\": 27}\'\\nu3 = User.model_validate_json(json_str)</code></pre>\\n\\n<p>All three paths produce a <code>User</code> instance. The difference is\\nwhere the raw data starts: already-keyword arguments, a Python dictionary, or a\\nJSON string.</p>\\n\\n<h3 id=\\"why-pydantic-fields-are-written-in-the-class-body\\">Why Pydantic fields are written in the class body</h3>\\n\\n<p>This is the part that can feel strange if you just learned ordinary class\\nvariables. In a normal class, <code>roles = []</code> in the class body is a\\nshared class variable. In a Pydantic <code>BaseModel</code>, annotated fields\\nin the class body are treated as model-field declarations. Pydantic reads those\\nannotations when the class is created and builds its own validation and\\nconstruction logic.</p>\\n\\n<pre><code class=\\"language-python\\">class User(BaseModel):\\n    id: int                 # model field declaration\\n    name: str               # model field declaration\\n    roles: list[str] = []   # Pydantic copies this safely per instance\\n\\nalice = User(id=1, name=\\"Alice\\")\\nbob = User(id=2, name=\\"Bob\\")\\n\\nalice.roles.append(\\"admin\\")\\nprint(bob.roles)\\n# []</code></pre>\\n\\n<p>So the syntax looks class-level, but the meaning is not the same as an\\nordinary mutable class variable. Pydantic uses the class definition as a schema\\nfor constructing validated instances. If you want the explicit style that also\\nworks in dataclasses, use <code>Field(default_factory=list)</code> for mutable\\ndefaults.</p>\\n\\n<h2 id=\\"6-validation-errors-are-part-of-the-contract\\">6) Validation Errors Are Part of the Contract</h2>\\n\\n<p>Good validation is not just \\"reject bad data.\\" It should tell the caller\\nexactly what failed, where it failed, and why.</p>\\n\\n<pre><code class=\\"language-python\\">from pydantic import BaseModel, ValidationError\\n\\nclass User(BaseModel):\\n    id: int\\n    name: str\\n\\ntry:\\n    User(id=\\"not-a-number\\", name=123)\\nexcept ValidationError as exc:\\n    print(exc.errors())</code></pre>\\n\\n<p>The error payload contains locations such as <code>(\\"id\\",)</code>, an error\\nmessage, an error type, and the bad input. FastAPI turns this into an HTTP 422\\nresponse for request-body validation failures.</p>\\n\\n<pre><code class=\\"language-json\\">[\\n  {\\n    \\"type\\": \\"int_parsing\\",\\n    \\"loc\\": [\\"id\\"],\\n    \\"msg\\": \\"Input should be a valid integer, unable to parse string as an integer\\",\\n    \\"input\\": \\"not-a-number\\"\\n  }\\n]</code></pre>\\n\\n<h2 id=\\"7-required-optional-nullable-and-defaults\\">7) Required, Optional, Nullable, and Defaults</h2>\\n\\n<p>This is one of the most important Pydantic topics because Python developers\\noften mix up \\"optional\\" and \\"nullable.\\"</p>\\n\\n<pre><code class=\\"language-python\\">from pydantic import BaseModel\\n\\nclass Customer(BaseModel):\\n    id: int                    # required, cannot be missing\\n    name: str                  # required, cannot be missing\\n    age: int | None            # required, but may be null/None\\n    nickname: str | None = None # optional and nullable\\n    country: str = \\"AU\\"         # optional, default used if missing</code></pre>\\n\\n<table>\\n  <thead>\\n    <tr><th>Declaration</th><th>May be missing?</th><th>May be <code>None</code>?</th><th>Meaning</th></tr>\\n  </thead>\\n  <tbody>\\n    <tr><td><code>name: str</code></td><td>No</td><td>No</td><td>Required non-null string</td></tr>\\n    <tr><td><code>age: int | None</code></td><td>No</td><td>Yes</td><td>Required key, value may be null</td></tr>\\n    <tr><td><code>nickname: str | None = None</code></td><td>Yes</td><td>Yes</td><td>Optional key, null/default allowed</td></tr>\\n    <tr><td><code>country: str = \\"AU\\"</code></td><td>Yes</td><td>No</td><td>Optional key with non-null default</td></tr>\\n  </tbody>\\n</table>\\n\\n<div class=\\"tr-tip\\">\\n  <strong>API design rule:</strong> do not write <code>age: int = None</code>.\\n  If <code>None</code> is valid, say so in the type: <code>age: int | None = None</code>.\\n  If <code>None</code> is not valid, use a real default or make the field required.\\n</div>\\n\\n<h2 id=\\"8-field-constraints-with-field\\">8) Field Constraints with <code>Field</code></h2>\\n\\n<p>Type annotations describe the broad shape. <code>Field</code> describes\\nconstraints, aliases, examples, and metadata for JSON schema/OpenAPI.</p>\\n\\n<pre><code class=\\"language-python\\">from decimal import Decimal\\nfrom pydantic import BaseModel, Field\\n\\nclass Product(BaseModel):\\n    sku: str = Field(min_length=3, max_length=32, pattern=r\\"^[A-Z0-9-]+$\\")\\n    name: str = Field(min_length=1)\\n    price: Decimal = Field(gt=0, max_digits=10, decimal_places=2)\\n    tags: list[str] = Field(default_factory=list, max_length=10)\\n\\nproduct = Product(sku=\\"SKU-100\\", name=\\"Keyboard\\", price=\\"129.95\\")\\nprint(product.price)\\n# Decimal(\'129.95\')</code></pre>\\n\\n<p>Use constraints for domain rules that can be stated locally on one field:\\nminimum length, maximum length, numeric range, regex/pattern, decimal precision,\\ndefault factories, examples, and descriptions.</p>\\n\\n<h2 id=\\"9-coercion-mode-vs-strict-mode\\">9) Coercion Mode vs Strict Mode</h2>\\n\\n<p>Pydantic\'s default behavior is intentionally practical: it tries to convert\\ncompatible values. This is commonly called <strong>lax mode</strong> or\\ncoercive validation. That is the normal API\\nmode because external data often arrives as strings.</p>\\n\\n<pre><code class=\\"language-python\\">from pydantic import BaseModel\\n\\nclass SearchParams(BaseModel):\\n    top_k: int\\n    include_archived: bool = False\\n\\nparams = SearchParams(top_k=\\"10\\", include_archived=\\"false\\")\\nprint(params)\\n# top_k=10 include_archived=False</code></pre>\\n\\n<p>A product payload shows the same idea across several JSON-compatible\\ntypes:</p>\\n\\n<pre><code class=\\"language-python\\">from pydantic import BaseModel\\n\\nclass Product(BaseModel):\\n    name: str\\n    price: float\\n    in_stock: bool\\n\\nproduct = Product.model_validate({\\n    \\"name\\": \\"Keyboard\\",\\n    \\"price\\": \\"19.99\\",   # str -&gt; float\\n    \\"in_stock\\": \\"true\\", # str -&gt; bool\\n})</code></pre>\\n\\n<p>Lax mode does not mean \\"anything becomes anything.\\" Pydantic v2 is more\\ncareful than older examples: for example, an integer is not automatically\\naccepted as a string field unless you explicitly configure that behavior.</p>\\n\\n<p>For money movement, security policy, compliance checks, or any place where\\nconversion could hide a bug, use strict validation.</p>\\n\\n<pre><code class=\\"language-python\\">from pydantic import BaseModel, ConfigDict, ValidationError\\n\\nclass StrictSearchParams(BaseModel):\\n    model_config = ConfigDict(strict=True)\\n\\n    top_k: int\\n    include_archived: bool = False\\n\\ntry:\\n    StrictSearchParams(top_k=\\"10\\")\\nexcept ValidationError as exc:\\n    print(exc.errors()[0][\\"msg\\"])\\n    # Input should be a valid integer</code></pre>\\n\\n<p>You can also make selected fields strict instead of making the whole model\\nstrict.</p>\\n\\n<pre><code class=\\"language-python\\">from pydantic import BaseModel, Field\\n\\nclass Payment(BaseModel):\\n    amount_cents: int = Field(strict=True, gt=0)\\n    currency: str</code></pre>\\n\\n<h2 id=\\"10-aliases-json-camelcase-and-python-snake-case\\">10) Aliases: JSON <code>camelCase</code> and Python <code>snake_case</code></h2>\\n\\n<p>External APIs often use <code>camelCase</code>. Python code should use\\n<code>snake_case</code>. Pydantic aliases let you support both without leaking\\nJSON naming conventions into internal code.</p>\\n\\n<pre><code class=\\"language-python\\">from pydantic import BaseModel, ConfigDict, Field\\n\\nclass UserProfile(BaseModel):\\n    model_config = ConfigDict(validate_by_name=True, validate_by_alias=True)\\n\\n    user_id: str = Field(alias=\\"userId\\")\\n    personal_email: str = Field(alias=\\"personalEmail\\")\\n\\npayload = {\\"userId\\": \\"u_123\\", \\"personalEmail\\": \\"alice@example.com\\"}\\nprofile = UserProfile.model_validate(payload)\\n\\nprint(profile.personal_email)\\n# alice@example.com\\n\\nprint(profile.model_dump(by_alias=True))\\n# {\'userId\': \'u_123\', \'personalEmail\': \'alice@example.com\'}</code></pre>\\n\\n<p>In real systems, aliases are a contract boundary. Internal code should speak\\nPython. External JSON should speak the API contract.</p>\\n\\n<h3 id=\\"alias-generator-for-large-apis\\">Alias generator for large APIs</h3>\\n\\n<pre><code class=\\"language-python\\">from pydantic import BaseModel, ConfigDict\\n\\ndef to_camel(name: str) -&gt; str:\\n    first, *rest = name.split(\\"_\\")\\n    return first + \\"\\".join(word.capitalize() for word in rest)\\n\\nclass ApiModel(BaseModel):\\n    model_config = ConfigDict(\\n        alias_generator=to_camel,\\n        validate_by_name=True,\\n        validate_by_alias=True,\\n    )\\n\\nclass Account(ApiModel):\\n    account_id: str\\n    billing_email: str\\n\\naccount = Account.model_validate({\\"accountId\\": \\"a_1\\", \\"billingEmail\\": \\"ops@example.com\\"})\\nprint(account.model_dump(by_alias=True))</code></pre>\\n\\n<p>Pydantic also provides common alias helpers. If your whole API uses\\ncamelCase, prefer a shared base model instead of repeating\\n<code>Field(alias=...)</code> everywhere.</p>\\n\\n<pre><code class=\\"language-python\\">from pydantic import BaseModel, ConfigDict\\nfrom pydantic.alias_generators import to_camel\\n\\nclass ApiModel(BaseModel):\\n    model_config = ConfigDict(\\n        alias_generator=to_camel,\\n        validate_by_name=True,\\n        validate_by_alias=True,\\n    )\\n\\nclass User(ApiModel):\\n    first_name: str\\n\\nuser = User.model_validate({\\"firstName\\": \\"Alice\\"})\\nprint(user.model_dump(by_alias=True))\\n# {\'firstName\': \'Alice\'}\\nprint(user.model_dump())\\n# {\'first_name\': \'Alice\'}</code></pre>\\n\\n<div class=\\"tr-note\\">\\n  <strong>Older examples:</strong> you may see <code>populate_by_name=True</code>\\n  in Pydantic v2 material. For current v2 code, prefer the more explicit\\n  pair <code>validate_by_name=True</code> and\\n  <code>validate_by_alias=True</code>.\\n</div>\\n\\n<h2 id=\\"11-nested-models\\">11) Nested Models</h2>\\n\\n<p>Real JSON payloads are rarely flat. A model can contain other models, lists\\nof models, dictionaries of models, enums, and constrained fields.</p>\\n\\n<pre><code class=\\"language-python\\">from enum import Enum\\nfrom pydantic import BaseModel, Field\\n\\nclass Plan(str, Enum):\\n    FREE = \\"free\\"\\n    TEAM = \\"team\\"\\n    ENTERPRISE = \\"enterprise\\"\\n\\nclass Address(BaseModel):\\n    line1: str\\n    city: str\\n    country: str = \\"AU\\"\\n\\nclass Organisation(BaseModel):\\n    org_id: str\\n    plan: Plan\\n    billing_address: Address\\n    admins: list[str] = Field(default_factory=list)\\n\\norg = Organisation.model_validate({\\n    \\"org_id\\": \\"org_123\\",\\n    \\"plan\\": \\"enterprise\\",\\n    \\"billing_address\\": {\\"line1\\": \\"1 Market St\\", \\"city\\": \\"Sydney\\"},\\n    \\"admins\\": [\\"alice@example.com\\", \\"bob@example.com\\"],\\n})\\n\\nprint(org.billing_address.city)\\n# Sydney</code></pre>\\n\\n<p>If a nested field fails, the error path points to the nested location, such\\nas <code>billing_address.city</code> or <code>admins.1</code>. That makes\\nvalidation errors actionable for both frontend engineers and API clients.</p>\\n\\n<h2 id=\\"12-validators-field-level-and-model-level-rules\\">12) Validators: Field-Level and Model-Level Rules</h2>\\n\\n<p>Use built-in types and <code>Field</code> constraints first. Add validators\\nwhen the rule is domain-specific or depends on multiple fields.</p>\\n\\n<h3 id=\\"field-validators\\">Field validators</h3>\\n\\n<pre><code class=\\"language-python\\">from pydantic import BaseModel, field_validator\\n\\nclass Signup(BaseModel):\\n    email: str\\n    display_name: str\\n\\n    @field_validator(\\"email\\")\\n    @classmethod\\n    def email_must_look_valid(cls, value: str) -&gt; str:\\n        value = value.strip().lower()\\n        if \\"@\\" not in value:\\n            raise ValueError(\\"email must contain @\\")\\n        return value\\n\\nsignup = Signup(email=\\" ALICE@EXAMPLE.COM \\", display_name=\\"Alice\\")\\nprint(signup.email)\\n# alice@example.com</code></pre>\\n\\n<h3 id=\\"model-validators\\">Model validators</h3>\\n\\n<p>Use a model validator when the rule needs more than one field.</p>\\n\\n<pre><code class=\\"language-python\\">from pydantic import BaseModel, model_validator\\n\\nclass DateRange(BaseModel):\\n    start_day: int\\n    end_day: int\\n\\n    @model_validator(mode=\\"after\\")\\n    def end_must_not_precede_start(self):\\n        if self.end_day &lt; self.start_day:\\n            raise ValueError(\\"end_day must be greater than or equal to start_day\\")\\n        return self</code></pre>\\n\\n<div class=\\"tr-note\\">\\n  <strong>Pydantic v1 to v2 naming:</strong> older notes and examples often use\\n  <code>@validator</code>, <code>@root_validator</code>, <code>.dict()</code>,\\n  <code>.json()</code>, and <code>parse_raw()</code>. In modern Pydantic v2,\\n  prefer <code>@field_validator</code>, <code>@model_validator</code>,\\n  <code>model_dump()</code>, <code>model_dump_json()</code>,\\n  <code>model_validate()</code>, and <code>model_validate_json()</code>.\\n</div>\\n\\n<div class=\\"tr-update\\">\\n  <strong>FastAPI compatibility:</strong> current FastAPI development is on\\n  Pydantic v2. FastAPI 0.128.0 removed support for importing models through\\n  <code>pydantic.v1</code>. Treat v1 syntax as migration material, not a pattern\\n  for new endpoints, and test framework/Pydantic upgrades together because\\n  request validation and generated OpenAPI are part of the API contract.\\n</div>\\n\\n<h2 id=\\"13-model-configuration-class-level-behavior-for-fields\\">13) Model Configuration: Class-Level Behavior for Fields</h2>\\n\\n<p>Configuration controls model-wide behavior. In Pydantic v2, use\\n<code>model_config = ConfigDict(...)</code>. This is where you set behavior\\nfor the model as a whole. Use <code>Field(...)</code> when the rule belongs to\\none field; use <code>model_config</code> when the rule belongs to all fields or\\nthe model contract.</p>\\n\\n<pre><code class=\\"language-python\\">from pydantic import BaseModel, ConfigDict, Field\\n\\nclass SecurePayload(BaseModel):\\n    model_config = ConfigDict(\\n        extra=\\"forbid\\",\\n        str_strip_whitespace=True,\\n        validate_assignment=True,\\n        frozen=False,\\n    )\\n\\n    tenant_id: str = Field(min_length=1)\\n    user_id: str = Field(min_length=1)\\n\\npayload = SecurePayload(tenant_id=\\" acme \\", user_id=\\" u_123 \\")\\nprint(payload.tenant_id)\\n# acme</code></pre>\\n\\n<table>\\n  <thead>\\n    <tr><th>Config</th><th>Why it matters</th></tr>\\n  </thead>\\n  <tbody>\\n    <tr><td><code>extra=\\"forbid\\"</code></td><td>Reject unknown fields instead of silently ignoring them. Good for security-sensitive APIs.</td></tr>\\n    <tr><td><code>extra=\\"ignore\\"</code></td><td>Ignore unknown fields. Useful when consuming third-party APIs that add fields over time.</td></tr>\\n    <tr><td><code>extra=\\"allow\\"</code></td><td>Keep unknown fields. Useful for flexible metadata, but avoid it for core contracts.</td></tr>\\n    <tr><td><code>strict=True</code></td><td>Disable broad coercion. Good when conversion could hide defects.</td></tr>\\n    <tr><td><code>validate_default=True</code></td><td>Validate default values too, instead of trusting them silently.</td></tr>\\n    <tr><td><code>validate_assignment=True</code></td><td>Validate when fields are changed after model creation.</td></tr>\\n    <tr><td><code>frozen=True</code></td><td>Make models immutable after creation. Useful for config and value objects.</td></tr>\\n    <tr><td><code>str_strip_whitespace=True</code></td><td>Normalize incoming strings at the boundary.</td></tr>\\n  </tbody>\\n</table>\\n\\n<h3 id=\\"extra-fields-the-default-is-usually-ignore-but-sensitive-apis-should-forbid\\">Extra fields: the default is usually ignore, but sensitive APIs should forbid</h3>\\n\\n<p>By default, Pydantic v2 ignores unknown fields. That is useful when consuming\\nexternal APIs that may add fields over time. For your own security-sensitive\\nrequest contracts, prefer <code>extra=\\"forbid\\"</code> so a misspelled or\\nunexpected field becomes a validation error.</p>\\n\\n<pre><code class=\\"language-python\\">from pydantic import BaseModel, ConfigDict, ValidationError\\n\\nclass Model(BaseModel):\\n    model_config = ConfigDict(extra=\\"forbid\\")\\n    field1: int\\n\\ntry:\\n    Model(field1=10, field2=20)\\nexcept ValidationError as exc:\\n    print(exc.errors()[0][\\"type\\"])\\n    # extra_forbidden</code></pre>\\n\\n<h3 id=\\"validate-defaults-when-defaults-can-be-wrong\\">Validate defaults when defaults can be wrong</h3>\\n\\n<p>Defaults are usually trusted. If a default itself might violate the declared\\ntype or constraints, set <code>validate_default=True</code>.</p>\\n\\n<pre><code class=\\"language-python\\">from pydantic import BaseModel, ConfigDict, ValidationError\\n\\nclass Model(BaseModel):\\n    model_config = ConfigDict(validate_default=True)\\n    field1: int | None = None\\n\\n# Valid because the type explicitly allows None.\\nModel()\\n\\nclass BadDefault(BaseModel):\\n    model_config = ConfigDict(validate_default=True)\\n    field1: int = None\\n\\ntry:\\n    BadDefault()\\nexcept ValidationError as exc:\\n    print(exc.errors()[0][\\"msg\\"])\\n    # Input should be a valid integer</code></pre>\\n\\n<h3 id=\\"validate-assignment-when-objects-are-modified-after-creation\\">Validate assignment when objects are modified after creation</h3>\\n\\n<p>Without assignment validation, Pydantic validates during construction but\\ndoes not automatically check every later attribute assignment. Enable\\n<code>validate_assignment=True</code> when models remain mutable but must stay\\nvalid.</p>\\n\\n<pre><code class=\\"language-python\\">from pydantic import BaseModel, ConfigDict, ValidationError\\n\\nclass Model(BaseModel):\\n    model_config = ConfigDict(validate_assignment=True)\\n    field: int\\n\\nm = Model(field=1)\\n\\ntry:\\n    m.field = \\"hello\\"\\nexcept ValidationError as exc:\\n    print(exc.errors()[0][\\"msg\\"])</code></pre>\\n\\n<h3 id=\\"use-frozen-models-when-mutation-should-be-blocked\\">Use frozen models when mutation should be blocked</h3>\\n\\n<p><code>frozen=True</code> makes the model immutable after construction.\\nThis is useful for configuration objects, value objects, and contracts where\\nlater mutation would make reasoning harder.</p>\\n\\n<pre><code class=\\"language-python\\">from pydantic import BaseModel, ConfigDict, ValidationError\\n\\nclass Model(BaseModel):\\n    model_config = ConfigDict(frozen=True)\\n    field: int\\n\\nm = Model(field=10)\\n\\ntry:\\n    m.field = 20\\nexcept ValidationError as exc:\\n    print(exc.errors()[0][\\"msg\\"])\\n    # Instance is frozen</code></pre>\\n\\n<h2 id=\\"14-deserialization-and-serialization\\">14) Deserialization and Serialization</h2>\\n\\n<p>Deserialization means turning external data into Python objects.\\nSerialization means turning Python objects back into dictionaries or JSON.</p>\\n\\n<h3 id=\\"validate-a-python-dictionary\\">Validate a Python dictionary</h3>\\n\\n<pre><code class=\\"language-python\\">from pydantic import BaseModel\\n\\nclass User(BaseModel):\\n    id: int\\n    name: str\\n\\ndata = {\\"id\\": \\"123\\", \\"name\\": \\"Alice\\"}\\nuser = User.model_validate(data)</code></pre>\\n\\n<h3 id=\\"validate-json-text\\">Validate JSON text</h3>\\n\\n<pre><code class=\\"language-python\\">json_data = \'{\\"id\\": \\"123\\", \\"name\\": \\"Alice\\"}\'\\nuser = User.model_validate_json(json_data)</code></pre>\\n\\n<h3 id=\\"serialize-to-a-python-dictionary-or-json-string\\">Serialize to a Python dictionary or JSON string</h3>\\n\\n<pre><code class=\\"language-python\\">print(user.model_dump())\\n# {\'id\': 123, \'name\': \'Alice\'}\\n\\nprint(user.model_dump_json())\\n# {\\"id\\":123,\\"name\\":\\"Alice\\"}</code></pre>\\n\\n<p><code>model_dump(mode=\\"python\\")</code> may include Python-native objects such\\nas <code>datetime</code> and <code>Decimal</code>. Use\\n<code>mode=\\"json\\"</code> or <code>model_dump_json()</code> when preparing data\\nfor JSON responses, logs, queues, or cache entries.</p>\\n\\n<h2 id=\\"15-json-schema-and-openapi\\">15) JSON Schema and OpenAPI</h2>\\n\\n<p>Pydantic can produce JSON Schema from your model. FastAPI uses that schema\\nto generate OpenAPI documentation and request/response examples.</p>\\n\\n<pre><code class=\\"language-python\\">from pydantic import BaseModel, Field\\n\\nclass CreateTicket(BaseModel):\\n    title: str = Field(min_length=3, examples=[\\"Reset my VPN access\\"])\\n    priority: int = Field(ge=1, le=5, description=\\"1 is highest priority\\")\\n\\nprint(CreateTicket.model_json_schema())</code></pre>\\n\\n<p>This is why FastAPI can show a form-like documentation page for your request\\nbody: the Pydantic model is both runtime validation and machine-readable API\\ncontract.</p>\\n\\n<h2 id=\\"16-typeadapter-validate-a-type-without-creating-a-model\\">16) TypeAdapter: Validate a Type Without Creating a Model</h2>\\n\\n<p>Sometimes you do not need a named model. You just need to validate\\n<code>list[int]</code>, <code>dict[str, Decimal]</code>, or\\n<code>list[SomeModel]</code>. Use <code>TypeAdapter</code>.</p>\\n\\n<pre><code class=\\"language-python\\">from pydantic import BaseModel, TypeAdapter\\n\\nclass Item(BaseModel):\\n    id: int\\n    name: str\\n\\nadapter = TypeAdapter(list[Item])\\n\\nitems = adapter.validate_python([\\n    {\\"id\\": \\"1\\", \\"name\\": \\"Keyboard\\"},\\n    {\\"id\\": 2, \\"name\\": \\"Mouse\\"},\\n])\\n\\nprint(items)\\n# [Item(id=1, name=\'Keyboard\'), Item(id=2, name=\'Mouse\')]</code></pre>\\n\\n<p><code>TypeAdapter</code> is useful for validating lists from files, queue\\nbatches, third-party responses, and LLM output arrays without inventing a\\nwrapper model.</p>\\n\\n<h2 id=\\"17-settings-management-with-pydantic-settings\\">17) Settings Management with <code>pydantic-settings</code></h2>\\n\\n<p>In Pydantic v2, settings moved to the separate\\n<code>pydantic-settings</code> package. Use it to read environment variables,\\n<code>.env</code> files, and secrets into a typed object.</p>\\n\\n<pre><code class=\\"language-bash\\">pip install pydantic-settings</code></pre>\\n\\n<pre><code class=\\"language-python\\">from pydantic import Field\\nfrom pydantic_settings import BaseSettings, SettingsConfigDict\\n\\nclass Settings(BaseSettings):\\n    model_config = SettingsConfigDict(\\n        env_file=\\".env\\",\\n        env_prefix=\\"APP_\\",\\n        extra=\\"ignore\\",\\n    )\\n\\n    app_name: str = \\"tutorial-api\\"\\n    debug: bool = False\\n    database_url: str\\n    jwt_audience: str = Field(default=\\"tutorial-api\\")\\n\\nsettings = Settings()\\nprint(settings.database_url)</code></pre>\\n\\n<p>With <code>env_prefix=\\"APP_\\"</code>, Pydantic reads variables such as\\n<code>APP_DATABASE_URL</code>, <code>APP_DEBUG</code>, and\\n<code>APP_JWT_AUDIENCE</code>. This follows twelve-factor application practice:\\nconfiguration belongs in the environment, not hard-coded in source files.</p>\\n\\n<div class=\\"tr-warning\\">\\n  <strong>Do not log settings objects blindly.</strong> If a settings model\\n  contains secrets, mark them as <code>SecretStr</code> or keep logging focused\\n  on non-sensitive fields.\\n</div>\\n\\n<h2 id=\\"18-fastapi-integration-request-and-response-contracts\\">18) FastAPI Integration: Request and Response Contracts</h2>\\n\\n<p>FastAPI uses Pydantic models in two directions:</p>\\n\\n<ul>\\n  <li><strong>Request models</strong> validate data coming into your endpoint.</li>\\n  <li><strong>Response models</strong> define and filter data leaving your endpoint.</li>\\n</ul>\\n\\n<pre><code class=\\"language-python\\">from decimal import Decimal\\nfrom fastapi import FastAPI\\nfrom pydantic import BaseModel, ConfigDict, Field\\n\\napp = FastAPI()\\n\\nclass CreateProductRequest(BaseModel):\\n    sku: str = Field(min_length=3)\\n    name: str\\n    price: Decimal = Field(gt=0)\\n\\nclass ProductResponse(BaseModel):\\n    model_config = ConfigDict(from_attributes=True)\\n\\n    sku: str\\n    name: str\\n    price: Decimal\\n\\n@app.post(\\"/products\\", response_model=ProductResponse)\\ndef create_product(req: CreateProductRequest):\\n    # req is already validated here.\\n    product = save_product(req)\\n    # response_model controls what leaves the API.\\n    return product</code></pre>\\n\\n<p><code>response_model</code> is not just documentation. It prevents accidental\\ndata leaks by shaping the returned object. If your internal object has\\n<code>cost_price</code>, <code>supplier_token</code>, or other private fields,\\nthey are not included unless the response model declares them.</p>\\n\\n<h2 id=\\"19-external-api-and-queue-message-validation\\">19) External API and Queue Message Validation</h2>\\n\\n<p>Pydantic is not only for incoming HTTP requests. Use it whenever your system\\nreceives data it did not create.</p>\\n\\n<pre><code class=\\"language-python\\">from datetime import datetime\\nfrom pydantic import BaseModel, ConfigDict, Field\\n\\nclass PaymentEvent(BaseModel):\\n    model_config = ConfigDict(extra=\\"forbid\\")\\n\\n    event_id: str\\n    tenant_id: str\\n    amount_cents: int = Field(gt=0)\\n    occurred_at: datetime\\n\\ndef handle_message(raw_json: str) -&gt; None:\\n    event = PaymentEvent.model_validate_json(raw_json)\\n    process_payment_event(event)</code></pre>\\n\\n<p>This pattern is useful for Pub/Sub messages, Kafka events, webhook payloads,\\ncron job inputs, uploaded JSON files, and service-to-service responses.</p>\\n\\n<h2 id=\\"20-llm-output-validation\\">20) LLM Output Validation</h2>\\n\\n<p>Pydantic gained renewed importance with LLM systems because model outputs\\nare probabilistic. Even when you ask for JSON, you still need to validate the\\nshape before using it in application code.</p>\\n\\n<pre><code class=\\"language-python\\">from pydantic import BaseModel, Field, ValidationError\\n\\nclass SupportTriage(BaseModel):\\n    category: str\\n    confidence: float = Field(ge=0, le=1)\\n    summary: str = Field(min_length=1)\\n    next_action: str\\n\\nraw_llm_json = \'\'\'\\n{\\n  \\"category\\": \\"account_access\\",\\n  \\"confidence\\": 0.87,\\n  \\"summary\\": \\"User cannot access VPN after password reset.\\",\\n  \\"next_action\\": \\"route_to_identity_team\\"\\n}\\n\'\'\'\\n\\ntry:\\n    triage = SupportTriage.model_validate_json(raw_llm_json)\\nexcept ValidationError as exc:\\n    # Retry, ask the model to repair, or send to human review.\\n    raise\\n\\nprint(triage.next_action)</code></pre>\\n\\n<p>In production LLM workflows, Pydantic is a guardrail, not a guarantee. It\\nchecks structure and local constraints. You still need business-rule validation,\\nauthorization checks, rate limits, audit logs, and human review for high-risk\\nactions.</p>\\n\\n<h2 id=\\"21-pydantic-dataclasses\\">21) Pydantic Dataclasses</h2>\\n\\n<p>Pydantic can also validate dataclasses. This is useful when you prefer\\ndataclass style but want Pydantic validation on construction.</p>\\n\\n<pre><code class=\\"language-python\\">from pydantic import ConfigDict, ValidationError\\nfrom pydantic.dataclasses import dataclass\\n\\n@dataclass(config=ConfigDict(validate_assignment=True))\\nclass Job:\\n    job_id: int\\n    queue: str\\n\\njob = Job(job_id=\\"42\\", queue=\\"email\\")\\nprint(job.job_id)\\n# 42\\n\\ntry:\\n    job.job_id = \\"not-an-int\\"\\nexcept ValidationError as exc:\\n    print(exc.errors()[0][\\"msg\\"])</code></pre>\\n\\n<p>Use this when integrating with dataclass-heavy code. For API contracts,\\nsettings, and OpenAPI integration, <code>BaseModel</code> is still the usual\\nchoice.</p>\\n\\n<h2 id=\\"22-practical-design-patterns\\">22) Practical Design Patterns</h2>\\n\\n<h3 id=\\"separate-input-domain-and-output-models\\">Separate input, domain, and output models</h3>\\n\\n<p>Do not use one giant model for every layer. API inputs, internal domain\\nobjects, database records, and API responses have different responsibilities.</p>\\n\\n<pre><code class=\\"language-python\\">from pydantic import BaseModel, Field\\n\\nclass CreateUserRequest(BaseModel):\\n    email: str\\n    display_name: str = Field(min_length=1)\\n\\nclass UserRecord(BaseModel):\\n    user_id: str\\n    tenant_id: str\\n    email: str\\n    display_name: str\\n    password_hash: str\\n\\nclass UserResponse(BaseModel):\\n    user_id: str\\n    email: str\\n    display_name: str</code></pre>\\n\\n<p>This avoids two common mistakes: accepting fields the client should not\\ncontrol, and returning fields the client should never see.</p>\\n\\n<h3 id=\\"validate-at-boundaries-not-everywhere\\">Validate at boundaries, not everywhere</h3>\\n\\n<p>Validate when data enters the system. Inside the system, pass typed objects.\\nRepeated validation in every function makes code noisy and hides the real\\ntrust boundary.</p>\\n\\n<h3 id=\\"prefer-explicit-models-over-unstructured-dictionaries\\">Prefer explicit models over unstructured dictionaries</h3>\\n\\n<pre><code class=\\"language-python\\"># Weak boundary\\ndef create_ticket(payload: dict) -&gt; dict:\\n    return {\\"title\\": payload[\\"title\\"], \\"priority\\": int(payload[\\"priority\\"])}\\n\\n# Strong boundary\\nclass CreateTicket(BaseModel):\\n    title: str\\n    priority: int = Field(ge=1, le=5)\\n\\ndef create_ticket(payload: CreateTicket) -&gt; dict:\\n    return {\\"title\\": payload.title, \\"priority\\": payload.priority}</code></pre>\\n\\n<h2 id=\\"23-common-pitfalls\\">23) Common Pitfalls</h2>\\n\\n<table>\\n  <thead>\\n    <tr><th>Pitfall</th><th>Better approach</th></tr>\\n  </thead>\\n  <tbody>\\n    <tr><td>Using <code>dict</code> for every payload</td><td>Create named models for important contracts.</td></tr>\\n    <tr><td>Confusing optional with nullable</td><td>Use <code>T | None</code> only when <code>None</code> is valid.</td></tr>\\n    <tr><td>Letting extra fields pass through sensitive APIs</td><td>Use <code>extra=\\"forbid\\"</code> for strict input contracts.</td></tr>\\n    <tr><td>Using one model for create/update/response/database</td><td>Split models by responsibility.</td></tr>\\n    <tr><td>Trusting LLM JSON without validation</td><td>Validate with a model or <code>TypeAdapter</code>, then apply business checks.</td></tr>\\n    <tr><td>Teaching v1 decorators in new code</td><td>Use v2 methods: <code>field_validator</code>, <code>model_validator</code>, <code>model_dump</code>.</td></tr>\\n    <tr><td>Logging secrets from settings</td><td>Use secret types and controlled logging.</td></tr>\\n  </tbody>\\n</table>\\n\\n<h2 id=\\"24-end-to-end-example-api-payload-alias-validation-and-response\\">24) End-to-End Example: API Payload, Alias, Validation, and Response</h2>\\n\\n<p>This example combines the pieces: JSON aliases, strict API shape, field\\nconstraints, model-level validation, and response shaping.</p>\\n\\n<pre><code class=\\"language-python\\">from decimal import Decimal\\nfrom fastapi import FastAPI\\nfrom pydantic import BaseModel, ConfigDict, Field, model_validator\\n\\napp = FastAPI()\\n\\nclass PurchaseRequest(BaseModel):\\n    model_config = ConfigDict(\\n        extra=\\"forbid\\",\\n        validate_by_name=True,\\n        validate_by_alias=True,\\n    )\\n\\n    tenant_id: str = Field(alias=\\"tenantId\\", min_length=1)\\n    user_id: str = Field(alias=\\"userId\\", min_length=1)\\n    sku: str = Field(min_length=3)\\n    quantity: int = Field(alias=\\"qty\\", gt=0, le=100)\\n    unit_price: Decimal = Field(alias=\\"unitPrice\\", gt=0)\\n\\n    @model_validator(mode=\\"after\\")\\n    def total_must_be_reasonable(self):\\n        total = self.quantity * self.unit_price\\n        if total &gt; Decimal(\\"50000\\"):\\n            raise ValueError(\\"purchase requires manual approval\\")\\n        return self\\n\\nclass PurchaseResponse(BaseModel):\\n    purchase_id: str = Field(alias=\\"purchaseId\\")\\n    status: str\\n    total: Decimal\\n\\n@app.post(\\"/purchase\\", response_model=PurchaseResponse)\\ndef create_purchase(req: PurchaseRequest):\\n    total = req.quantity * req.unit_price\\n    return {\\n        \\"purchaseId\\": \\"po_123\\",\\n        \\"status\\": \\"accepted\\",\\n        \\"total\\": total,\\n    }</code></pre>\\n\\n<p>The endpoint can now rely on <code>req.tenant_id</code>,\\n<code>req.user_id</code>, <code>req.quantity</code>, and\\n<code>req.unit_price</code> having already passed the declared contract. The\\nexternal JSON can still use <code>tenantId</code>, <code>userId</code>,\\n<code>qty</code>, and <code>unitPrice</code>.</p>\\n\\n<h2 id=\\"25-decision-guide\\">25) Decision Guide</h2>\\n\\n<table>\\n  <thead>\\n    <tr><th>Need</th><th>Use</th></tr>\\n  </thead>\\n  <tbody>\\n    <tr><td>Internal trusted data container</td><td><code>dataclass</code></td></tr>\\n    <tr><td>HTTP request/response contract</td><td><code>BaseModel</code></td></tr>\\n    <tr><td>Environment configuration</td><td><code>pydantic-settings</code> <code>BaseSettings</code></td></tr>\\n    <tr><td>Validate a list/dict/primitive type directly</td><td><code>TypeAdapter</code></td></tr>\\n    <tr><td>Use dataclass syntax but add validation</td><td><code>pydantic.dataclasses.dataclass</code></td></tr>\\n    <tr><td>Strict financial/security data</td><td><code>ConfigDict(strict=True)</code> or strict fields</td></tr>\\n    <tr><td>Frontend camelCase with Python snake_case</td><td><code>Field(alias=...)</code> or <code>alias_generator</code></td></tr>\\n    <tr><td>LLM structured output</td><td><code>BaseModel</code> or <code>TypeAdapter</code> plus business-rule checks</td></tr>\\n  </tbody>\\n</table>\\n\\n<h2 id=\\"26-what-to-remember\\">26) What to Remember</h2>\\n\\n<ul>\\n  <li>Plain classes and dataclasses organize data but do not validate runtime input by default.</li>\\n  <li>Pydantic models are boundary contracts: validate, convert, serialize, and document data.</li>\\n  <li>Default Pydantic mode is practical and coercive; use strict mode where conversion is risky.</li>\\n  <li>Optional means \\"may be missing\\" only when there is a default. Nullable means the type includes <code>None</code>.</li>\\n  <li>Aliases let external JSON use <code>camelCase</code> while Python remains <code>snake_case</code>.</li>\\n  <li>Use v2 APIs in new code: <code>model_validate</code>, <code>model_dump</code>, <code>field_validator</code>, <code>model_validator</code>, and <code>ConfigDict</code>.</li>\\n  <li>Pydantic is also useful beyond FastAPI: settings, webhooks, queues, external APIs, files, and LLM output validation.</li>\\n</ul>\\n\\n<h2 id=\\"official-references\\">Official references</h2>\\n<ul>\\n  <li><a href=\\"https://docs.pydantic.dev/latest/\\">Pydantic documentation</a></li>\\n  <li><a href=\\"https://docs.pydantic.dev/latest/migration/\\">Pydantic v2 migration guide</a></li>\\n  <li><a href=\\"https://fastapi.tiangolo.com/how-to/migrate-from-pydantic-v1-to-pydantic-v2/\\">FastAPI: migrate from Pydantic v1 to v2</a></li>\\n  <li><a href=\\"https://fastapi.tiangolo.com/tutorial/body/\\">FastAPI request body models</a></li>\\n</ul>"}'),r={title:"Pydantic Data Models: From Python Classes to API Contracts",slug:"/part2-backend-platform-security/04-pydantic-data-models",description:"FastAPI uses Pydantic because web applications live at the boundary between untyped external data and typed Python code. This chapter starts from ordinary Python classes, moves through dataclasses, then shows why Pyda...",sidebar_label:"4. Pydantic data models",pagination_label:"4. Pydantic data models",hide_title:!0,hide_table_of_contents:!0},l=void 0,c={},p=[];function u(e){return(0,o.jsx)(i.A,{content:d})}function m(e={}){const{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,o.jsx)(n,{...e,children:(0,o.jsx)(u,{...e})}):u()}}}]);